// ---------------------------------------------------------------------------
// LETRA CLÁSICA ('py-dial'): contornos de Cinzel Regular (Version 2.000), de
// Natanael Gama, SIL Open Font License 1.1 (permite incrustar y convertir a
// curvas). Unidades de la fuente (upm 1000), y hacia ARRIBA, más el
// interletraje de cada pareja.
//
// MOVIDA TAL CUAL el 2026-11-22 desde el antiguo lib/watch-glyphs.ts (que
// escribió scripts/gen-watch-glyphs.mjs): la tabla es byte a byte la misma
// (comprobado: JSON.stringify(GLYPH_PY_DIAL) === JSON.stringify(antiguo
// GLYPH_FONTS["py-dial"])). La fuente Cinzel con la que se generó NO está en
// el repo: esta tabla NO se regenera ni se edita a mano. La usan el texto de
// la esfera, el anillo fijo de la tapa y el grabado "Clásica"; cambiarla
// movería todas esas letras. Solo si llegan los originales "PY Dial" del
// taller se vuelve a generar, a propósito, con
//   node scripts/gen-watch-glyphs.mjs --solo clasica --clasica <fuente> …
// (ver la cabecera del generador). La letra fina vive aparte, en
// lib/watch-glyphs-fina.ts, y regenerarla no toca este archivo.
//
// Aquí vive también la interfaz GlyphFont: la usan las dos tablas y el barril
// lib/watch-glyphs.ts, sin ciclos de importación.
// ---------------------------------------------------------------------------
export interface GlyphFont {
  family: string;
  upm: number;
  /** carácter → [avance, trazo SVG en unidades de la fuente, y hacia arriba] */
  glyphs: Readonly<Record<string, readonly [number, string]>>;
  /** "AV" → ajuste en unidades (negativo = se juntan) */
  kern: Readonly<Record<string, number>>;
}

